package checks

import (
	"fmt"
	"regexp"
	"strings"

	"claudinite.com/checksdk"
)

// A paper's folder is references/<slug>/<slug>.pdf. Intake is finished when the
// digest makes that PDF redundant and the paper has its row in the index, so a
// folder carrying a PDF needs both a digest.md and a README link to it.
const (
	referencesIndex = "references/README.md"
	paperPDF        = `^references/([^/_][^/]*)/([^/]+)\.pdf$`
)

var paperPDFPath = regexp.MustCompile(paperPDF)

func init() {
	checksdk.Register(checksdk.Check{
		ID:     "paper-folder-indexed",
		Tags:   []string{"world"},
		OnFail: "block",
		Since:  "2026-10-16",
		Doc:    ".claudinite/local/packs/vascular-coloring/skills/paper-intake/SKILL.md",
		Why:    "a paper is only finished when its digest makes the PDF redundant and the index points at it — a folder with a PDF but no digest sends the next session back into the PDF, and one the index omits is a paper nobody knows is already digested",
		Run:    paperFolderIndexed,
	})
}

func paperFolderIndexed(repo checksdk.Repo) []checksdk.Finding {
	tracked := map[string]bool{}
	for _, f := range repo.Tracked() {
		tracked[f] = true
	}
	index, _ := repo.Read(referencesIndex)
	var out []checksdk.Finding
	for _, file := range repo.Tracked() {
		m := paperPDFPath.FindStringSubmatch(file)
		if m == nil || m[1] != m[2] {
			continue
		}
		slug := m[1]
		digest := "references/" + slug + "/digest.md"
		if !tracked[digest] {
			out = append(out, checksdk.Finding{
				Path:     file,
				Sentence: fmt.Sprintf("%s has no digest.md beside its PDF", slug),
				Fix:      fmt.Sprintf("write %s following the paper-intake skill, so the PDF never has to be reopened", digest),
			})
			continue
		}
		if !strings.Contains(index, "("+slug+"/digest.md)") {
			out = append(out, checksdk.Finding{
				Path:     referencesIndex,
				Sentence: fmt.Sprintf("%s is not linked from the paper index", slug),
				Fix:      fmt.Sprintf("add its row to the Papers table in %s, linking (%s/digest.md)", referencesIndex, slug),
			})
		}
	}
	return out
}
package checks

import "testing"

const (
	paperPDFFile = "references/smith-2024-vessels/smith-2024-vessels.pdf"
	paperDigest  = "references/smith-2024-vessels/digest.md"
)

func TestPaperFolderIndexedFiresOnAPDFWithNoDigest(t *testing.T) {
	fs := run(t, paperFolderIndexed, map[string]string{
		paperPDFFile:    "%PDF",
		referencesIndex: "| [x](smith-2024-vessels/digest.md) |",
	}, paperPDFFile, referencesIndex)
	wantCount(t, fs, 1)
	wantMatch(t, fs[0].Sentence, `smith-2024-vessels has no digest\.md`)
}

func TestPaperFolderIndexedFiresOnADigestTheIndexOmits(t *testing.T) {
	fs := run(t, paperFolderIndexed, map[string]string{
		paperPDFFile:    "%PDF",
		paperDigest:     "# digest",
		referencesIndex: "| [other](other-2020-x/digest.md) |",
	}, paperPDFFile, paperDigest, referencesIndex)
	wantCount(t, fs, 1)
	if fs[0].Path != referencesIndex {
		t.Errorf("finding on %s, want %s", fs[0].Path, referencesIndex)
	}
	wantMatch(t, fs[0].Sentence, `smith-2024-vessels is not linked`)
}

func TestPaperFolderIndexedIsQuietOnADigestedIndexedPaperAndOnToolsAndSupplements(t *testing.T) {
	fs := run(t, paperFolderIndexed, map[string]string{
		paperPDFFile:    "%PDF",
		paperDigest:     "# digest",
		referencesIndex: "| [**smith**](smith-2024-vessels/digest.md) |",
		"references/smith-2024-vessels/supplementary/data.pdf": "%PDF",
		"references/_tools/notes.pdf":                         "%PDF",
	}, paperPDFFile, paperDigest, referencesIndex,
		"references/smith-2024-vessels/supplementary/data.pdf", "references/_tools/notes.pdf")
	wantCount(t, fs, 0)
}
package checks

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"

	"claudinite.com/checksdk"
)

// The px -> um scale of every figure comes from ONE measured table: UM_PER_BAR
// and SCALEBAR_PX in analysis/measure_vessels.py. annotate_overlays.py reads them
// by importing from there, never by carrying its own copy — that is the invariant
// this check holds.
//
// Companion to scale-numbers-match-calibration, which holds the numbers quoted in
// *markdown* to that table. Markdown is all that check reads, so a second table
// defined in Python is invisible to it: the two rules cover opposite halves of the
// same single-source line.
//
// Parse rather than grep: the names are stripped of comments and of every string
// literal (including the docstrings that spell the table out) first, and only an
// assignment — `NAME =`, or an annotated `NAME: dict =` — counts. A docstring
// quoting "SCALEBAR_PX = {'fig1': 61}" documents the table; it does not define it.
const calibrationSource = "analysis/measure_vessels.py"

var (
	calibrationNames = []string{"UM_PER_BAR", "SCALEBAR_PX"}
	// An assignment ends at an `=` that is not the first half of `==`, which the
	// caller tests on the character after the match.
	calibrationAssign = regexp.MustCompile(`^\s*(` + strings.Join(calibrationNames, "|") + `)\s*(?::[^=\n]+)?=`)
)

func init() {
	checksdk.Register(checksdk.Check{
		ID:     "calibration-single-source",
		Tags:   []string{"world"},
		OnFail: "block",
		Since:  "2026-07-29",
		Doc:    ".claudinite/local/packs/vascular-coloring/RULES.md",
		Why:    "UM_PER_BAR / SCALEBAR_PX are a measurement, not a constant — a second definition means two calibrations, and the one a given script happens to read wins silently, re-labelling its lengths and densities with a scale nobody re-measured",
		Run:    calibrationSingleSource,
	})
}

// pythonCode blanks out comments and string literals, keeping every newline and
// every column so line numbers and the assignment shape survive. Handles ''' / """
// blocks, single-quoted strings and escapes; a `#` inside a string is not a comment.
func pythonCode(text string) string {
	src := []rune(text)
	out := make([]rune, 0, len(src))
	var quote []rune // the open delimiter, or nil
	startsWith := func(i int, s []rune) bool {
		if i+len(s) > len(src) {
			return false
		}
		for k, r := range s {
			if src[i+k] != r {
				return false
			}
		}
		return true
	}
	blank := func(n int) {
		for ; n > 0; n-- {
			out = append(out, ' ')
		}
	}
	for i := 0; i < len(src); {
		c := src[i]
		if quote != nil {
			if c == '\\' && len(quote) == 1 {
				blank(2)
				i += 2
				continue
			}
			if startsWith(i, quote) {
				blank(len(quote))
				i += len(quote)
				quote = nil
				continue
			}
			if c == '\n' {
				out = append(out, '\n')
			} else {
				out = append(out, ' ')
			}
			i++
			continue
		}
		if c == '#' { // to end of line
			for i < len(src) && src[i] != '\n' {
				out = append(out, ' ')
				i++
			}
			continue
		}
		if c == '"' || c == '\'' {
			triple := []rune{c, c, c}
			if startsWith(i, triple) {
				quote = triple
			} else {
				quote = []rune{c}
			}
			blank(len(quote))
			i += len(quote)
			continue
		}
		out = append(out, c)
		i++
	}
	return string(out)
}

type calibrationDef struct {
	name string
	line int
}

// calibrationDefs is every line of text that assigns one of the calibration names.
// Only statements count: a line that starts inside an open bracket is a continuation,
// where `UM_PER_BAR=50` is a keyword argument being passed, not the table being defined.
func calibrationDefs(text string) []calibrationDef {
	var out []calibrationDef
	depth := 0
	for i, line := range strings.Split(pythonCode(text), "\n") {
		if depth == 0 {
			if m := calibrationAssign.FindStringSubmatchIndex(line); m != nil && !strings.HasPrefix(line[m[1]:], "=") {
				out = append(out, calibrationDef{line[m[2]:m[3]], i + 1})
			}
		}
		for _, c := range line {
			switch c {
			case '(', '[', '{':
				depth++
			case ')', ']', '}':
				depth = max(0, depth-1)
			}
		}
	}
	return out
}

func calibrationSingleSource(repo checksdk.Repo) []checksdk.Finding {
	var out []checksdk.Finding
	for _, file := range repo.Tracked() {
		if !strings.HasSuffix(file, ".py") || strings.HasPrefix(file, shared) {
			continue
		}
		text, ok := repo.Read(file)
		if !ok {
			continue
		}
		defs := calibrationDefs(text)

		if file == calibrationSource {
			// The source file itself: a name assigned twice is the same drift, one
			// file in. The later assignment wins and the earlier measurement is dead
			// code that still reads as the calibration.
			for _, name := range calibrationNames {
				var lines []string
				last := 0
				for _, d := range defs {
					if d.name == name {
						lines = append(lines, strconv.Itoa(d.line))
						last = d.line
					}
				}
				if len(lines) < 2 {
					continue
				}
				out = append(out, checksdk.Finding{
					Path:     file,
					Line:     last,
					Sentence: fmt.Sprintf("%s is assigned %d times in %s (lines %s)", name, len(lines), calibrationSource, strings.Join(lines, ", ")),
					Fix:      fmt.Sprintf("keep one %s assignment — delete the copies, or if the bar was re-measured, replace the single definition with the new value", name),
				})
			}
			continue
		}

		for _, d := range defs {
			out = append(out, checksdk.Finding{
				Path:     file,
				Line:     d.line,
				Sentence: fmt.Sprintf("%s defines its own %s", file, d.name),
				Fix:      fmt.Sprintf("import it instead — `from measure_vessels import %s`, the way the overlay script already reads the table; if a bar really was re-measured, change the value in %s, the one place it is measured", d.name, calibrationSource),
			})
		}
	}
	return out
}
package checks

import (
	"fmt"
	"regexp"
	"slices"
	"strings"

	"claudinite.com/checksdk"
)

// Every render the pipeline produces is written into a directory the script
// creates for itself (measure_vessels.py --overlays -> analysis/overlays/,
// annotate_overlays.py -> analysis/annotated/). Those directories are gitignored,
// which is what makes "regenerate, never commit" hold under a `git add -A` or an
// agent staging a whole directory.
//
// Sibling of rendered-overlays-untracked, from the other side: that rule fires once
// a render is already tracked (the damage), this one keeps the ignore entry that
// stops it getting there. A newly added output directory is the real gap — it is
// gitignored only if someone remembers.
//
// Parse rather than grep: an output directory is one the script actually creates
// (`os.makedirs(...)`), resolved through the script's own `HERE` constant, with
// comments and string literals handled — a path mentioned in a docstring is not a
// directory anything writes to.
var (
	hereDef = regexp.MustCompile(`(?m)^\s*HERE\s*=\s*os\.path\.dirname\(\s*os\.path\.abspath\(\s*__file__\s*\)\s*\)`)
	// NAME = os.path.join(HERE, 'annotated')  /  os.path.join(HERE, 'a', 'b')
	hereJoin  = regexp.MustCompile(`(?:^|[^\w.])([A-Za-z_]\w*)\s*=\s*os\.path\.join\(\s*HERE\s*,\s*((?:'[^']*'|"[^"]*")(?:\s*,\s*(?:'[^']*'|"[^"]*"))*)\s*\)`)
	makedirs  = regexp.MustCompile(`os\.makedirs\(\s*([A-Za-z_]\w*)\b`)
	joinParts = regexp.MustCompile(`'([^']*)'|"([^"]*)"`)
)

func init() {
	checksdk.Register(checksdk.Check{
		ID:     "render-outputs-gitignored",
		Tags:   []string{"world"},
		OnFail: "block",
		Since:  "2026-07-29",
		Doc:    ".claudinite/local/packs/vascular-coloring/skills/vessel-overlay-review/SKILL.md",
		Why:    "overlay renders are regenerated from the scripts, not data — an output directory that is not ignored gets swept into the repo by the first `git add -A` after a run, and from then on a stale PNG is what reviewers see instead of what the current script draws",
		Run:    renderOutputsGitignored,
	})
}

func dirOf(file string) string {
	if i := strings.LastIndex(file, "/"); i >= 0 {
		return file[:i]
	}
	return ""
}

func joinPath(parts ...string) string {
	var kept []string
	for _, p := range parts {
		if p != "" {
			kept = append(kept, p)
		}
	}
	return strings.Join(kept, "/")
}

type createdDir struct {
	path string
	line int
}

// createdDirs is the directories a script creates under its own location, as
// repo-relative paths with the line of the makedirs call. Empty unless HERE is the
// script's own dir — an unrecognised layout is left alone rather than guessed at.
// Comments are stripped and string literals kept: the joined path segments ARE
// literals.
func createdDirs(file, source string) []createdDir {
	text := uncomment(source)
	if !hereDef.MatchString(text) {
		return nil
	}
	here := dirOf(file)
	consts := map[string]string{}
	for _, m := range hereJoin.FindAllStringSubmatch(text, -1) {
		segs := []string{here}
		escapes := false
		for _, p := range joinParts.FindAllStringSubmatch(m[2], -1) {
			s := p[1] + p[2] // only one of the two alternatives took part
			escapes = escapes || s == ".." || s == ""
			segs = append(segs, s)
		}
		if escapes { // escapes the script's dir
			continue
		}
		consts[m[1]] = joinPath(segs...)
	}
	var out []createdDir
	seen := map[string]bool{}
	for _, m := range makedirs.FindAllStringSubmatchIndex(text, -1) {
		path, ok := consts[text[m[2]:m[3]]]
		if !ok || path == "" || seen[path] {
			continue
		}
		seen[path] = true
		out = append(out, createdDir{path, lineAt(text, m[0])})
	}
	return out
}

type ignorePattern struct {
	base, path        string
	negated, anchored bool
}

// ignorePatterns is the ignore patterns that can cover dir: git reads a .gitignore
// per directory, so every ancestor of dir gets one — root first, deepest last, which
// is also git's precedence order (the last matching pattern wins). A .gitignore
// *inside* dir is excluded: it cannot cause its own directory to be ignored. Each
// path is normalised to a repo-relative path or a bare name git matches at any
// depth below that .gitignore's directory.
func ignorePatterns(repo checksdk.Repo, dir string) []ignorePattern {
	parts := strings.Split(dir, "/")
	segs := parts[:len(parts)-1]
	bases := []string{""}
	for i := range segs {
		b := strings.Join(segs[:i+1], "/")
		if !slices.Contains(bases, b) {
			bases = append(bases, b)
		}
	}
	var out []ignorePattern
	for _, base := range bases {
		text, ok := repo.Read(joinPath(base, ".gitignore"))
		if !ok {
			continue
		}
		for _, raw := range strings.Split(text, "\n") {
			line := trim(raw)
			if line == "" || strings.HasPrefix(line, "#") {
				continue
			}
			negated := strings.HasPrefix(line, "!")
			body := line
			if negated {
				body = line[1:]
			}
			body = strings.TrimRight(body, "/")
			if body == "" {
				continue
			}
			p := ignorePattern{base: base, negated: negated, anchored: strings.Contains(body, "/"), path: body}
			if p.anchored {
				p.path = joinPath(base, strings.TrimLeft(body, "/"))
			}
			out = append(out, p)
		}
	}
	return out
}

func (p ignorePattern) covers(dir string) bool {
	if p.anchored {
		return dir == p.path || strings.HasPrefix(dir, p.path+"/")
	}
	// A bare name matches any path component at or below the .gitignore's directory.
	return (dir == p.base || strings.HasPrefix(dir, p.base+"/") || p.base == "") &&
		slices.Contains(strings.Split(dir, "/"), p.path)
}

// ignored follows git: the last matching pattern wins, negation included.
func ignored(repo checksdk.Repo, dir string) bool {
	var last *ignorePattern
	for _, p := range ignorePatterns(repo, dir) {
		if p.covers(dir) {
			last = &p
		}
	}
	return last != nil && !last.negated
}

func renderOutputsGitignored(repo checksdk.Repo) []checksdk.Finding {
	var out []checksdk.Finding
	for _, file := range repo.Tracked() {
		if !strings.HasSuffix(file, ".py") || strings.HasPrefix(file, shared) {
			continue
		}
		text, ok := repo.Read(file)
		if !ok {
			continue
		}
		for _, dir := range createdDirs(file, text) {
			if ignored(repo, dir.path) {
				continue
			}
			out = append(out, checksdk.Finding{
				Path:     file,
				Line:     dir.line,
				Sentence: fmt.Sprintf("%s renders into %s/, which no .gitignore entry covers", file, dir.path),
				Fix:      fmt.Sprintf("add `/%s/` to .gitignore (with a comment naming the command that regenerates it, as the existing render entries do); if %s/ holds real data or agreed ground truth rather than renders, it belongs under references/ instead", dir.path, dir.path),
			})
		}
	}
	return out
}
# vascular-coloring — this repo's own pack

The **vessel-image quantification** domain this project works in: gP-CD31 (red) confocal panels
measured for categorize / count / measure. A local pack — declared by hand as
`local/vascular-coloring` in `.claudinite-settings.json`, never fingerprinted.

It carries only the imaging-specific part: the research loop, ground-truth discipline and
anti-overfitting stance are `research-project`'s, so reach for that pack for those.

## Checks (`rules`)

| Check | Enforces (≤5 words) | Severity |
|---|---|---|
| `overlay-color-contrast` | no red marks on red signal | blocking |
| `rendered-overlays-untracked` | rendered overlays stay uncommitted | blocking |
| `panel-scale-calibration` | every working figure stays calibrated | blocking |
| `scale-numbers-match-calibration` | quoted µm/px matches its source | blocking |
| `locked-metric-fields` | locked metrics stay reported | blocking |
| `calibration-single-source` | one calibration table, imported | blocking |
| `render-outputs-gitignored` | render directories stay ignored | blocking |
| `paper-folder-indexed` | each paper digested and indexed | blocking |

The checks are Go, in [`checks/`](checks/). Fixtures: the `*_test.go` files beside them — each
check shown firing on a violating input and quiet on a clean one, run with `go test` in a scratch
module whose `go.mod` carries the stanza `cn check sdk --out <dir>` writes.

## Prose (`RULES.md`)

| Rule (marker) | How enforced |
|---|---|
| `never-self-validate` | prose |
| `progress-visual-assertion` | prose (+ the `vessel-overlay-review` skill) |
| `locked-metric-definitions` | prose (+ `locked-metric-fields`) |
| `per-paper-rollup` | prose |
| `paper-finished-pdf-redundant` | prose (+ the `paper-intake` skill) |
| `trustworthy-numbers` | prose |

## Skills

| Skill | Trigger |
|---|---|
| [vessel-overlay-review](skills/vessel-overlay-review/SKILL.md) | proposing, revising or reporting on the extraction pipeline |
| [paper-intake](skills/paper-intake/SKILL.md) | a research paper is added to `references/`, or one needs re-processing |
| [image-algorithm-development](skills/image-algorithm-development/SKILL.md) | starting, resuming or iterating on an image detection, segmentation or reading algorithm |

